package xz

import (
	"bytes"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The golden vectors in testdata are generated by testdata/gen.py with
// Python's lzma module (liblzma), plus hand-built .xz containers and a few
// streams from the xz tool; gen.py checks each one against liblzma before
// writing it.

type goldenCompress struct {
	Format  int              `json:"format"`
	Check   int              `json:"check"`
	Preset  *int             `json:"preset"`
	Filters []map[string]any `json:"filters"`
}

type goldenCase struct {
	Name         string           `json:"name"`
	File         string           `json:"file"`
	Format       int              `json:"format"`
	Filters      []map[string]any `json:"filters"`
	Expect       []string         `json:"expect"`
	Error        bool             `json:"error"`
	AutoOK       bool             `json:"auto_ok"`
	Source       string           `json:"source"`
	Note         string           `json:"note"`
	PythonExpect []string         `json:"python_expect"`
	Compress     *goldenCompress  `json:"compress"`
}

type golden struct {
	Inputs map[string][]byte
	Cases  []goldenCase
}

func loadGolden(t testing.TB) *golden {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "manifest.json"))
	if err != nil {
		t.Fatal(err)
	}
	var m struct {
		Inputs []string     `json:"inputs"`
		Cases  []goldenCase `json:"cases"`
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	if err := dec.Decode(&m); err != nil {
		t.Fatal(err)
	}
	g := &golden{Inputs: map[string][]byte{}, Cases: m.Cases}
	for _, name := range m.Inputs {
		b, err := os.ReadFile(filepath.Join("testdata", "inputs", name+".bin"))
		if err != nil {
			t.Fatal(err)
		}
		g.Inputs[name] = b
	}
	return g
}

func (g *golden) data(t testing.TB, c goldenCase) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", "vectors", c.File))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func (g *golden) expect(names []string) []byte {
	out := []byte{}
	for _, n := range names {
		out = append(out, g.Inputs[n]...)
	}
	return out
}

func toFilters(t testing.TB, specs []map[string]any) []Filter {
	t.Helper()
	if specs == nil {
		return nil
	}
	fs := make([]Filter, len(specs))
	for i, m := range specs {
		f, err := FilterFromMap(m)
		if err != nil {
			t.Fatalf("filter %v: %v", m, err)
		}
		fs[i] = f
	}
	return fs
}

// TestGoldenDecode decodes every Python/liblzma vector and compares with
// the expected output (or expects an error where liblzma fails).
func TestGoldenDecode(t *testing.T) {
	g := loadGolden(t)
	for _, c := range g.Cases {
		t.Run(c.Name, func(t *testing.T) {
			data := g.data(t, c)
			got, err := Decompress(data, c.Format, toFilters(t, c.Filters))
			if c.Error {
				if err == nil {
					t.Fatalf("decoded %d bytes, want an error (%s)", len(got), c.Note)
				}
				var pe *panicError
				if errors.As(err, &pe) {
					t.Fatalf("panic inside the LZMA decoder: %v", err)
				}
				return
			}
			if err != nil {
				t.Fatalf("Decompress: %v", err)
			}
			if want := g.expect(c.Expect); !bytes.Equal(got, want) {
				t.Fatalf("output mismatch: got %d bytes, want %d", len(got), len(want))
			}
			if c.AutoOK {
				got, err := Decompress(data, FormatAuto, nil)
				if err != nil || !bytes.Equal(got, g.expect(c.Expect)) {
					t.Fatalf("FormatAuto: err=%v, match=%v", err, bytes.Equal(got, g.expect(c.Expect)))
				}
			}
		})
	}
}

// TestGoldenFilterBytes compares this package's delta/BCJ encoders with
// liblzma's byte for byte: decoding a raw [filter, LZMA2] vector with only
// LZMA2 yields liblzma's filtered bytes. It also checks that the vectors
// really exercise the filters (some bytes are converted).
func TestGoldenFilterBytes(t *testing.T) {
	g := loadGolden(t)
	n := 0
	for _, c := range g.Cases {
		if c.Format != FormatRaw || len(c.Filters) != 2 || c.Error || len(c.Expect) != 1 {
			continue
		}
		n++
		t.Run(c.Name, func(t *testing.T) {
			filters := toFilters(t, c.Filters)
			libFiltered, err := Decompress(g.data(t, c), FormatRaw, filters[1:])
			if err != nil {
				t.Fatal(err)
			}
			chain, err := parseChain(filters, true)
			if err != nil {
				t.Fatal(err)
			}
			input := g.Inputs[c.Expect[0]]
			ours := applyEncodeFilters(input, chain[:1])
			if !bytes.Equal(ours, libFiltered) {
				t.Fatalf("filtered bytes differ from liblzma's (first difference at %d)", firstDiff(ours, libFiltered))
			}
			changed := 0
			for i := range input {
				if input[i] != libFiltered[i] {
					changed++
				}
			}
			if changed < 50 {
				t.Fatalf("only %d bytes changed by the filter; vector does not exercise it", changed)
			}
			// And our decoder inverts liblzma's encoder.
			back := append([]byte(nil), libFiltered...)
			applyDecodeFilters(back, chain[:1])
			if !bytes.Equal(back, input) {
				t.Fatalf("decoding liblzma's filtered bytes differs at %d", firstDiff(back, input))
			}
			t.Logf("%d of %d bytes converted", changed, len(input))
		})
	}
	if n < 15 {
		t.Fatalf("only %d raw filter vectors found", n)
	}
}

func firstDiff(a, b []byte) int {
	for i := range a {
		if i >= len(b) || a[i] != b[i] {
			return i
		}
	}
	if len(a) != len(b) {
		return len(a)
	}
	return -1
}

// TestGoldenRoundTrip compresses every golden input with the same
// arguments Python used and decodes the result with this package.
func TestGoldenRoundTrip(t *testing.T) {
	g := loadGolden(t)
	for _, c := range g.Cases {
		if c.Compress == nil || len(c.Expect) != 1 {
			continue
		}
		t.Run(c.Name, func(t *testing.T) {
			in := g.Inputs[c.Expect[0]]
			comp, err := compressGolden(t, in, c.Compress)
			if err != nil {
				t.Fatal(err)
			}
			got, err := Decompress(comp, c.Format, toFilters(t, c.Filters))
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, in) {
				t.Fatalf("round trip mismatch at %d", firstDiff(got, in))
			}
			if c.Format == FormatXZ || c.Format == FormatAlone {
				if got, err := Decompress(comp, FormatAuto, nil); err != nil || !bytes.Equal(got, in) {
					t.Fatalf("FormatAuto: %v", err)
				}
			}
		})
	}
}

func compressGolden(t testing.TB, in []byte, c *goldenCompress) ([]byte, error) {
	preset := -1
	if c.Preset != nil {
		preset = *c.Preset
	}
	return Compress(in, c.Format, c.Check, preset, toFilters(t, c.Filters))
}

func TestGoldenCoverage(t *testing.T) {
	g := loadGolden(t)
	seen := map[string]bool{}
	for _, c := range g.Cases {
		seen[c.Name] = true
	}
	for _, want := range []string{
		"xz_empty", "alone_empty", "raw_lzma2_empty", "raw_lzma1_empty",
		"xz_check_none", "xz_check_crc32", "xz_check_crc64", "xz_check_sha256",
		"xz_preset0", "xz_preset9e", "xz_delta1_f32", "xz_delta8_f32", "xz_x86",
		"xz_powerpc", "xz_ia64", "xz_arm", "xz_armthumb", "xz_sparc",
		"raw_lzma1_lc4lp0pb4", "multi_xz_xz", "multi_alone_alone", "multi_auto_mixed",
		"hb_blocks_nosizes", "hb_stream_padding", "hb_chain3",
	} {
		if !seen[want] {
			t.Errorf("golden case %s missing", want)
		}
	}
	for _, c := range g.Cases {
		if strings.HasPrefix(c.Name, "xz_arm64") {
			return
		}
	}
	t.Log("no ARM64 vectors (gen.py ran without the xz tool)")
}
